#!/usr/bin/env bash
# Installs git pre-commit hook that runs ./scripts/ci_local.sh --fast
set -euo pipefail

HOOK=".git/hooks/pre-commit"
[[ -d ".git/hooks" ]] || { echo "Not a git repo."; exit 1; }

cat > "$HOOK" <<'EOF'
#!/usr/bin/env bash
# Auto-generated by scripts/install_hooks.sh
# Skip with: git commit --no-verify
set -e
./scripts/ci_local.sh --fast
EOF

chmod +x "$HOOK"
echo "✓ Installed pre-commit hook. Bypass with --no-verify."
